CREATE OR REPLACE FUNCTION public.debug_admin_check()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    _uid UUID;
    _jwt_email TEXT;
    _jwt_raw JSONB;
    _profile_role TEXT;
    _admin_result BOOLEAN;
BEGIN
    _uid := auth.uid();
    BEGIN
        _jwt_raw := auth.jwt();
        _jwt_email := _jwt_raw ->> 'email';
    EXCEPTION WHEN OTHERS THEN
        _jwt_raw := '{}'::JSONB;
        _jwt_email := 'ERROR: ' || SQLERRM;
    END;
    _admin_result := public.is_admin();
    SELECT role INTO _profile_role FROM public.profiles WHERE id = _uid;
    RETURN jsonb_build_object(
        'uid', COALESCE(_uid::TEXT, 'NULL'),
        'jwt_email', COALESCE(_jwt_email, 'NULL'),
        'profile_role', COALESCE(_profile_role, 'NULL'),
        'is_admin_result', _admin_result,
        'jwt_keys', COALESCE((SELECT jsonb_agg(key) FROM jsonb_object_keys(_jwt_raw) AS key), '[]'::JSONB)
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_exam_workflow_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
DECLARE
    _allowed BOOLEAN;
    _admin_only BOOLEAN;
BEGIN
    IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
        IF NEW.is_published AND NEW.status <> 'published' THEN
            RAISE EXCEPTION 'is_published = true faqat status = ''published'' bo''lganda ruxsat etiladi.'
                USING ERRCODE = 'check_violation';
        END IF;
        IF NEW.status = 'published' AND NEW.is_published IS DISTINCT FROM TRUE THEN
            RAISE EXCEPTION 'status = ''published'' uchun is_published = true bo''lishi shart.'
                USING ERRCODE = 'check_violation';
        END IF;
        RETURN NEW;
    END IF;

    _allowed := (OLD.status, NEW.status) IN (
        ('draft', 'review'),
        ('review', 'draft'),
        ('review', 'approved'),
        ('approved', 'published'),
        ('published', 'archived'),
        ('archived', 'draft')
    );

    IF NOT _allowed THEN
        RAISE EXCEPTION 'Noto''g''ri exam status o''tishi: "%" → "%". Ruxsat etilgan o''tishlar: %',
            OLD.status, NEW.status, public.exam_allowed_next_statuses(OLD.status)
            USING ERRCODE = 'check_violation';
    END IF;

    _admin_only := (OLD.status, NEW.status) IN (
        ('approved', 'published'),
        ('published', 'archived'),
        ('archived', 'draft')
    );

    IF _admin_only AND NOT public.is_admin() THEN
        RAISE EXCEPTION '"%" → "%" o''tishi faqat admin uchun ruxsat etilgan.',
            OLD.status, NEW.status
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF NOT _admin_only AND NOT (public.is_admin() OR public.is_reviewer()) THEN
        RAISE EXCEPTION '"%" → "%" o''tishi uchun reviewer yoki admin roli talab qilinadi.',
            OLD.status, NEW.status
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF NEW.is_published AND NEW.status <> 'published' THEN
        RAISE EXCEPTION 'is_published = true faqat status = ''published'' bo''lganda ruxsat etiladi.'
            USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.status = 'published' AND NEW.is_published IS DISTINCT FROM TRUE THEN
        RAISE EXCEPTION 'status = ''published'' uchun is_published = true bo''lishi shart.'
            USING ERRCODE = 'check_violation';
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_question_workflow_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
DECLARE
    _allowed BOOLEAN;
BEGIN
    IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
        RETURN NEW;
    END IF;

    _allowed := (OLD.status, NEW.status) IN (
        ('draft', 'review'),
        ('review', 'approved'),
        ('review', 'rejected'),
        ('rejected', 'draft')
    );

    IF NOT _allowed THEN
        RAISE EXCEPTION 'Noto''g''ri savol status o''tishi: "%" → "%". Ruxsat etilgan o''tishlar: %',
            OLD.status, NEW.status, public.question_allowed_next_statuses(OLD.status)
            USING ERRCODE = 'check_violation';
    END IF;

    IF NOT (public.is_admin() OR public.is_reviewer()) THEN
        RAISE EXCEPTION '"%" → "%" o''tishi uchun reviewer yoki admin roli talab qilinadi.',
            OLD.status, NEW.status
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    RETURN NEW;
END;
$function$

