CREATE OR REPLACE FUNCTION public.is_admin()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
DECLARE
    _uid UUID;
    _jwt_email TEXT;
    _profile_role TEXT;
    _profile_email TEXT;
    _auth_email TEXT;
BEGIN
    IF auth.role() = 'service_role' OR current_user = 'service_role' THEN
        RETURN TRUE;
    END IF;

    IF public.is_superadmin() THEN
        RETURN TRUE;
    END IF;

    _uid := auth.uid();

    BEGIN
        _jwt_email := LOWER(TRIM(COALESCE(auth.jwt() ->> 'email', '')));
    EXCEPTION WHEN OTHERS THEN
        _jwt_email := '';
    END;

    IF _jwt_email IN ('fsoyilov@gmail.com', 'admin@nihongo-talk.jp') THEN
        RETURN TRUE;
    END IF;

    IF _uid IS NOT NULL THEN
        SELECT LOWER(TRIM(COALESCE(email, ''))) INTO _auth_email FROM auth.users WHERE id = _uid;
        IF _auth_email IN ('fsoyilov@gmail.com', 'admin@nihongo-talk.jp') THEN
            RETURN TRUE;
        END IF;

        SELECT LOWER(TRIM(COALESCE(role, ''))), LOWER(TRIM(COALESCE(email, '')))
        INTO _profile_role, _profile_email
        FROM public.profiles
        WHERE id = _uid;

        IF _profile_email IN ('fsoyilov@gmail.com', 'admin@nihongo-talk.jp')
           OR _profile_role = 'admin'
           OR (_profile_role = 'superadmin' AND _profile_email = 'fsoyilov@gmail.com') THEN
            RETURN TRUE;
        END IF;
    END IF;

    RETURN FALSE;
END;
$function$

CREATE OR REPLACE FUNCTION public.is_reviewer()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
DECLARE
    _uid UUID := auth.uid();
    _role TEXT;
    _email TEXT;
BEGIN
    IF auth.role() = 'service_role' OR current_user = 'service_role' THEN
        RETURN TRUE;
    END IF;

    IF public.is_admin() THEN
        RETURN TRUE;
    END IF;

    IF _uid IS NULL THEN
        RETURN FALSE;
    END IF;

    SELECT LOWER(TRIM(COALESCE(role, ''))), LOWER(TRIM(COALESCE(email, '')))
    INTO _role, _email
    FROM public.profiles
    WHERE id = _uid;

    RETURN _role IN ('reviewer', 'admin', 'superadmin')
        OR _email IN ('fsoyilov@gmail.com', 'admin@nihongo-talk.jp');
END;
$function$

CREATE OR REPLACE FUNCTION public.is_superadmin()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
DECLARE
    _uid UUID;
    _jwt_email TEXT;
    _auth_email TEXT;
    _profile_email TEXT;
BEGIN
    IF auth.role() = 'service_role' OR current_user = 'service_role' THEN
        RETURN TRUE;
    END IF;

    _uid := auth.uid();

    BEGIN
        _jwt_email := LOWER(TRIM(COALESCE(auth.jwt() ->> 'email', '')));
    EXCEPTION WHEN OTHERS THEN
        _jwt_email := '';
    END;

    IF _jwt_email = 'fsoyilov@gmail.com' THEN
        RETURN TRUE;
    END IF;

    IF _uid IS NOT NULL THEN
        SELECT LOWER(TRIM(COALESCE(email, ''))) INTO _auth_email FROM auth.users WHERE id = _uid;
        IF _auth_email = 'fsoyilov@gmail.com' THEN
            RETURN TRUE;
        END IF;

        SELECT LOWER(TRIM(COALESCE(email, ''))) INTO _profile_email FROM public.profiles WHERE id = _uid;
        IF _profile_email = 'fsoyilov@gmail.com' THEN
            RETURN TRUE;
        END IF;
    END IF;

    RETURN FALSE;
END;
$function$

